/* Word Guess word lists.
   answers: common English 5-letter words, ranked from the hermitdave/FrequencyWords
   OpenSubtitles list, checked against the ENABLE word list, then reviewed by hand.
   valid: answers plus every other 5-letter word in dwyl/english-words and ENABLE.
   Stored as packed strings to keep the file small; both are arrays at runtime. */
(function () {
  var A = "";
  var X = "";
  var answers = A.match(/[a-z]{5}/g);
  window.WORDS = { answers: answers, valid: answers.concat(X.match(/[a-z]{5}/g)) };
})();
